/** Picking and bailing, the only Floor Distributors charge that is Terra's cost. */
export const FLOORDISTRIBUTORS_PICKING_FEE = 29.5;

export type FloorDistributorsRow = {
  /** timber | hybrid | vinyl */
  category: string;
  /** The sheet's own wording, kept for the audit trail. */
  printedCategory: string;
  brand: string;
  range: string;
  code: string;
  colour: string;
  /** Per m2 ex GST, read off THIS ROW. Colours of one range differ. */
  pricePerM2: number;
  /** Board length in mm. Part of the variant identity on Federation Plank. */
  lengthMm: number;
  widthMm: number;
  /** Total board thickness as printed. */
  thicknessMm: number;
  /** Vinyl and hybrid wear layer in mm. Null on engineered timber. */
  wearLayerMm: number | null;
  /** Integer board count, derived from the printed box m2 and asserted whole. */
  boardsPerBox: number;
  /** Real box m2 off the whole board count. ORDER OFF THIS ONE. */
  boxM2: number;
  /** The sheet's printed box m2, for cross-checking an invoice only. */
  boxM2Printed: number;
  /** The sheet's printed full-pallet m2. Freight information, not a price break. */
  palletM2Printed: number;
  /** Boxes on a pallet. Null where the printed pallet m2 does not divide whole. */
  boxesPerPallet: number | null;
  palletExact: boolean;
  /** The matching-scotia label the flooring sheet prints, verbatim. */
  matchLabel: string;
  /** Real Designer Profile Scotia item code, joined off matchLabel. */
  scotiaCode: string | null;
  /** true = the label named no scotia colour and the match was read, not printed. */
  scotiaInferred: boolean;
  /** The Viva rows print their trim in prose instead of a label. Kept as printed. */
  vivaStairNote: string;
  note: string;
  sourcePage: number;
};

export type FloorDistributorsAccessory = {
  /** accessory | underlay */
  category: string;
  printedCategory: string;
  brand: string;
  range: string;
  code: string;
  description: string;
  /** The colour or range list printed in the brackets, verbatim. */
  suitsPrinted: string;
  /** Real range names, only where the sheet named ranges. Empty on the timber scotia. */
  fitsRanges: string[];
  size: string;
  /** Ex GST, per `unit`. */
  price: number;
  /** $/m on a trim, $/piece on a custom stair. */
  unit: string;
  note: string;
  sourcePage: number;
};

export type FloorDistributorsUnderlay = {
  code: string;
  description: string;
  /** Metres on one roll. */
  rollM: number;
  /** Printed tier rates per lineal metre ex GST. */
  price1to9: number;
  price10to20: number;
  price20plus: number;
  /** The tier Damien chose to seed as the break, in rolls. */
  breakRolls: number;
  /** The same threshold in lineal metres, which is the unit it is priced in. */
  breakM: number;
  sourcePage: number;
};

/** A line on the price list that is deliberately not a product. */
export type FloorDistributorsDropped = { code: string; description: string; reason: string };

